{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/nav-actions.json
    The buttons at the end of a top bar: login, the call to action and the theme button (it only reports the press). No wrapper: they sit in the row of the bar.
    Props (p): login, loginHref, cta, ctaHref, actions, tone, themeLabel. -#}
{%- set v_login = (p.login ?? null) -%}
{%- set v_loginHref = (p.loginHref ?? '#/login') -%}
{%- set v_cta = (p.cta ?? null) -%}
{%- set v_ctaHref = (p.ctaHref ?? null) -%}
{%- set v_actions = (p.actions ?? 'cta') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_themeLabel = (p.themeLabel ?? null) -%}
{%- if ui_t(v_login) %}
  {%- set c_1 -%}
    {{ ui_text(v_login) }}
  {%- endset -%}
  {{ include('ui/button/button.html.twig', {'p': {'Variant': 'ghost', 'Size': 'sm', 'Href': ui_s(v_loginHref), 'Class': ui_s((ui_t(ui_eq(v_tone, 'inverse')) ? 'text-background hover:bg-background/10' : '')), 'Attrs': ui_attrs(['data-testid', 'nav-login'])}, 'children': c_1}, with_context = false) }}
{%- endif %}
{%- if ui_t(ui_and([ui_eq(v_actions, 'cta'), v_cta])) %}
  {%- set c_2 -%}
    {{ ui_text(v_cta) }}
  {%- endset -%}
  {{ include('ui/button/button.html.twig', {'p': {'Variant': ui_s((ui_t(ui_eq(v_tone, 'inverse')) ? 'secondary' : 'default')), 'Size': 'sm', 'Href': ui_s(v_ctaHref), 'Attrs': ui_attrs(['data-testid', 'header-cta'])}, 'children': c_2}, with_context = false) }}
{%- endif %}
{%- if ui_t(v_themeLabel) %}
  {%- set c_3 -%}
    {{ ui_text(v_themeLabel) }}
  {%- endset -%}
  {{ include('ui/button/button.html.twig', {'p': {'Variant': 'outline', 'Size': 'sm', 'Attrs': ui_attrs(['data-testid', 'theme-toggle'])}, 'children': c_3}, with_context = false) }}
{%- endif %}
